import ast,io,os,sys,textwrap,weakref,collections,itertools,contextlib,operator,json
from pathlib import Path
base=Path('.dedup-work/apt11-20261021')
def extract(file,names,env):
 tree=ast.parse((base/file).read_text()); tree.body=[n for n in tree.body if isinstance(n,(ast.ClassDef,ast.FunctionDef)) and n.name in names]; exec(compile(tree,str(base/file),'exec'),env); return env
term=extract('src--aptsources_cleanup--util--terminal.py',{'termwrap'},dict(textwrap=textwrap,weakref=weakref,sys=sys,os=os,collections=collections,fpartial=__import__('functools').partial))
results={}
for name,action in [('empty_wrapped_paragraph',lambda:term['termwrap'](io.StringIO(),width=20).print('',return_last_line_len=True)),('empty_paragraph_sequence',lambda:term['termwrap'](io.StringIO(),width=20).print_all([],return_last_line_len=True))]:
 try: results[name]={'value':action()}
 except Exception as e: results[name]={'exception':type(e).__name__,'message':str(e)}
env=extract('tools--zip.py',{'attrs2dict','itercontextmanager','getlines','_getlines_impl_generic','_getlines_impl_bytes'},dict(io=io,operator=operator,contextlib=contextlib,fpartial=__import__('functools').partial))
results['short_final_chunk']={'input_hex':b'abc'.hex(),'chunk_size':8,'delimiter_hex':b'\0'.hex(),'actual_hex':[bytes(x).hex() for x in env['getlines'](io.BytesIO(b'abc'),b'\0',8)],'expected_hex':[b'abc'.hex()]}
assert results['empty_wrapped_paragraph']['exception']=='IndexError'
assert results['empty_paragraph_sequence']['exception']=='IndexError'
assert results['short_final_chunk']['actual_hex']!=results['short_final_chunk']['expected_hex']
(base/'final-controls-result.json').write_text(json.dumps(results,indent=2)+'\n'); print(json.dumps(results,indent=2))
